\documentclass{article}
\usepackage{graphicx}
\title{Clinic Recruitment --- Interim Report}
\author{Field Team B}
\date{April 2026}
\begin{document}
\maketitle

\section{Recruitment}
Figure~\ref{fig:pipeline} illustrates the three-stage recruitment
pipeline that each district clinic follows, from community sensitisation
through screening to enrolment.
\begin{figure}
\centering
% example-image-a.pdf is the scanned flowchart of the recruitment pipeline
\includegraphics[width=0.7\linewidth]{example-image-a}
\caption{Bar chart of enrolled participants per district.}
\label{fig:pipeline}
\end{figure}

\section{Enrolment}
Figure~\ref{fig:enrolment} summarises how many participants each
district has enrolled so far, against the target of eighty per district.
\begin{figure}
\centering
% example-image-b.pdf is the bar chart of enrolment numbers
\includegraphics[width=0.7\linewidth]{example-image-b}
\caption{Flowchart of the three-stage clinic recruitment pipeline.}
\label{fig:enrolment}
\end{figure}

\section{Next steps}
Districts that are below sixty percent of target will receive an extra
sensitisation round before the next interim report.

\end{document}

